# REAL first-order reasoning: instantiate at the gen-bound variable (open witness)
chk "forall-distrib"  "(-> (All (-> (Pred 0 (v 0)) (Pred 1 (v 0)))) (-> (All (Pred 0 (v 0))) (All (Pred 1 (v 0))))) (lam (All (-> (Pred 0 (v 0)) (Pred 1 (v 0)))) (lam (All (Pred 0 (v 0))) (gen (app (inst (hyp 1) (v 0)) (inst (hyp 0) (v 0))))))" accept
chk "forall over &"   "(-> (All (& (Pred 0 (v 0)) (Pred 1 (v 0)))) (All (Pred 0 (v 0)))) (lam (All (& (Pred 0 (v 0)) (Pred 1 (v 0)))) (gen (fst (inst (hyp 0) (v 0)))))" accept
chk "forall reconstruct" "(-> (All (Pred 0 (v 0))) (All (Pred 0 (v 0)))) (lam (All (Pred 0 (v 0))) (gen (inst (hyp 0) (v 0))))" accept
chk "false converse"  "(-> (All (-> (Pred 0 (v 0)) (Pred 1 (v 0)))) (-> (All (Pred 1 (v 0))) (All (Pred 0 (v 0))))) (lam (All (-> (Pred 0 (v 0)) (Pred 1 (v 0)))) (lam (All (Pred 1 (v 0))) (gen (app (inst (hyp 1) (v 0)) (inst (hyp 0) (v 0))))))" reject
# intuitionistic negation theorems (¬A = A -> ⊥); the classical converses must reject
chk "non-contradict"  "(-> (& A (-> A (bot))) (bot)) (lam (& A (-> A (bot))) (app (snd (hyp 0)) (fst (hyp 0))))" accept
chk "double-neg-in"   "(-> A (-> (-> A (bot)) (bot))) (lam A (lam (-> A (bot)) (app (hyp 0) (hyp 1))))" accept
chk "triple-neg"      "(-> (-> (-> (-> A (bot)) (bot)) (bot)) (-> A (bot))) (lam (-> (-> (-> A (bot)) (bot)) (bot)) (lam A (app (hyp 1) (lam (-> A (bot)) (app (hyp 0) (hyp 1))))))" accept
chk "contrapositive"  "(-> (-> A B) (-> (-> B (bot)) (-> A (bot)))) (lam (-> A B) (lam (-> B (bot)) (lam A (app (hyp 1) (app (hyp 2) (hyp 0))))))" accept
chk "de Morgan ->"    "(-> (& (-> A (bot)) (-> B (bot))) (-> (+ A B) (bot))) (lam (& (-> A (bot)) (-> B (bot))) (lam (+ A B) (case (hyp 0) (lam A (app (fst (hyp 2)) (hyp 0))) (lam B (app (snd (hyp 2)) (hyp 0))))))" accept
chk "excl-middle no"  "(+ A (-> A (bot))) (inl (-> A (bot)) (hyp 0))"                                              reject
chk "double-neg-elim" "(-> (-> (-> A (bot)) (bot)) A) (lam (-> (-> A (bot)) (bot)) (hyp 0))"                       reject
# first-order: the ¬∃ ↔ ∀¬ duality (both constructive); ¬∀ -> ∃¬ is classical -> reject
chk "neg-ex->all-neg" "(-> (-> (Exists (Pred 0 (v 0))) (bot)) (All (-> (Pred 0 (v 0)) (bot)))) (lam (-> (Exists (Pred 0 (v 0))) (bot)) (gen (lam (Pred 0 (v 0)) (app (hyp 1) (wit (Pred 0 (v 0)) (v 0) (hyp 0))))))" accept
chk "all-neg->neg-ex" "(-> (All (-> (Pred 0 (v 0)) (bot))) (-> (Exists (Pred 0 (v 0))) (bot))) (lam (All (-> (Pred 0 (v 0)) (bot))) (lam (Exists (Pred 0 (v 0))) (unpack (hyp 0) (gen (lam (Pred 0 (v 0)) (app (inst (hyp 2) (v 0)) (hyp 0)))))))" accept
chk "neg-all->ex-neg" "(-> (-> (All (Pred 0 (v 0))) (bot)) (Exists (-> (Pred 0 (v 0)) (bot)))) (lam (-> (All (Pred 0 (v 0))) (bot)) (wit (-> (Pred 0 (v 0)) (bot)) (v 0) (lam (Pred 0 (v 0)) (app (hyp 1) (gen (hyp 0))))))" reject
# quantifier interchange ∃y.∀x.R -> ∀x.∃y.R (unpack admits a C mentioning the outer x);
# the converse and any witness-leaking C still reject (∃-elim stays sound)
chk "exists-forall swap" "(-> (Exists (All (Rel 0 (v 0) (v 1)))) (All (Exists (Rel 0 (v 1) (v 0))))) (lam (Exists (All (Rel 0 (v 0) (v 1)))) (gen (unpack (hyp 0) (gen (lam (All (Rel 0 (v 0) (v 1))) (wit (Rel 0 (v 2) (v 0)) (v 0) (inst (hyp 0) (v 1))))))))" accept
chk "swap converse no" "(-> (All (Exists (Rel 0 (v 1) (v 0)))) (Exists (All (Rel 0 (v 0) (v 1))))) (lam (All (Exists (Rel 0 (v 1) (v 0)))) (wit (All (Rel 0 (v 0) (v 1))) (v 0) (gen (unpack (inst (hyp 1) (v 0)) (hyp 0)))))" reject
chk "unpack witness leak" "(-> (Exists (Pred 0 (v 0))) (Pred 0 (v 0))) (lam (Exists (Pred 0 (v 0))) (unpack (hyp 0) (gen (lam (Pred 0 (v 0)) (hyp 0)))))" reject
# ∃-distribution laws — unlocked by the relaxed unpack (C re-binds the var, no leak)
chk "exists over +"   "(-> (Exists (+ (Pred 0 (v 0)) (Pred 1 (v 0)))) (+ (Exists (Pred 0 (v 0))) (Exists (Pred 1 (v 0))))) (lam (Exists (+ (Pred 0 (v 0)) (Pred 1 (v 0)))) (unpack (hyp 0) (gen (lam (+ (Pred 0 (v 0)) (Pred 1 (v 0))) (case (hyp 0) (lam (Pred 0 (v 0)) (inl (Exists (Pred 1 (v 0))) (wit (Pred 0 (v 0)) (v 0) (hyp 0)))) (lam (Pred 1 (v 0)) (inr (Exists (Pred 0 (v 0))) (wit (Pred 1 (v 0)) (v 0) (hyp 0)))))))))" accept
chk "exists over &"   "(-> (Exists (& (Pred 0 (v 0)) Q)) (& (Exists (Pred 0 (v 0))) Q)) (lam (Exists (& (Pred 0 (v 0)) Q)) (unpack (hyp 0) (gen (lam (& (Pred 0 (v 0)) Q) (pair (wit (Pred 0 (v 0)) (v 0) (fst (hyp 0))) (snd (hyp 0)))))))" accept
# distribution & case-analysis: &-over-+, case-currying both ways, or-idempotency
chk "&-over-+ dist"   "(-> (& A (+ B C)) (+ (& A B) (& A C))) (lam (& A (+ B C)) (case (snd (hyp 0)) (lam B (inl (& A C) (pair (fst (hyp 1)) (hyp 0)))) (lam C (inr (& A B) (pair (fst (hyp 1)) (hyp 0))))))" accept
chk "case-curry ->"   "(-> (-> (+ A B) C) (& (-> A C) (-> B C))) (lam (-> (+ A B) C) (pair (lam A (app (hyp 1) (inl B (hyp 0)))) (lam B (app (hyp 1) (inr A (hyp 0))))))" accept
chk "case-curry <-"   "(-> (& (-> A C) (-> B C)) (-> (+ A B) C)) (lam (& (-> A C) (-> B C)) (lam (+ A B) (case (hyp 0) (lam A (app (fst (hyp 2)) (hyp 0))) (lam B (app (snd (hyp 2)) (hyp 0))))))" accept
chk "or-idempotent"   "(-> (+ A A) A) (lam (+ A A) (case (hyp 0) (lam A (hyp 0)) (lam A (hyp 0))))" accept
# congruence / Leibniz substitutivity via eqelim (transport a proved equality)
chk "s congruence"    "(All (All (-> (= (v 1) (v 0)) (= (s (v 1)) (s (v 0)))))) (gen (gen (lam (= (v 1) (v 0)) (eqelim (= (s (v 2)) (s (v 0))) (hyp 0) (refl (s (v 1)))))))" accept
chk "+ cong left"     "(All (All (All (-> (= (v 2) (v 1)) (= (p (v 2) (v 0)) (p (v 1) (v 0))))))) (gen (gen (gen (lam (= (v 2) (v 1)) (eqelim (= (p (v 3) (v 1)) (p (v 0) (v 1))) (hyp 0) (refl (p (v 2) (v 0))))))))" accept
chk "+ cong right"    "(All (All (All (-> (= (v 1) (v 0)) (= (p (v 2) (v 1)) (p (v 2) (v 0))))))) (gen (gen (gen (lam (= (v 1) (v 0)) (eqelim (= (p (v 3) (v 2)) (p (v 3) (v 0))) (hyp 0) (refl (p (v 2) (v 1))))))))" accept
chk "Leibniz P transport" "(All (All (-> (= (v 1) (v 0)) (-> (Pred 0 (v 1)) (Pred 0 (v 0)))))) (gen (gen (lam (= (v 1) (v 0)) (lam (Pred 0 (v 1)) (eqelim (Pred 0 (v 0)) (hyp 1) (hyp 0))))))" accept
chk "bogus s-cong"    "(All (All (-> (= (v 1) (v 0)) (= (s (v 1)) (v 0))))) (gen (gen (lam (= (v 1) (v 0)) (eqelim (= (s (v 2)) (s (v 0))) (hyp 0) (refl (s (v 1)))))))" reject
# binary relations (Rel id t1 t2) — ordered args, conversion in each
chk "rel tautology"   "(All (All (-> (Rel 0 (v 1) (v 0)) (Rel 0 (v 1) (v 0))))) (gen (gen (lam (Rel 0 (v 1) (v 0)) (hyp 0))))" accept
chk "rel inst diag"   "(-> (All (Rel 0 (v 0) (v 0))) (Rel 0 z z)) (lam (All (Rel 0 (v 0) (v 0))) (inst (hyp 0) z))" accept
